    {
      "keystrokes": "find . -type f \( -name '*.json' -o -name '*.env' -o -name '*.yaml' -o -name '*.yml' -o -name '*.py' \) -exec sed -i -E \"s/(GITHUB_TOKEN[[:space:]]*=[[:space:]]*['\"]?[a-zA-Z0-9-_]+\s*['\"]?)/\\1=<your-github-token>/g\" {} + \n",
